-- LOCAL Auth/Storage metadata fixtures. HTTP file bytes and signed URLs require live checks.
begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
insert into auth.users(id) values('e1000000-0000-4000-8000-000000000001'),('e1000000-0000-4000-8000-000000000002');
create function pg_temp.ref_id(n integer) returns uuid language sql as $$select ('e2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ref_path(n integer) returns text language sql as $$select 'e1000000-0000-4000-8000-000000000001/references/e3000000-0000-4000-8000-000000000001/'||pg_temp.ref_id(n)::text||'.jpg'$$;
create function pg_temp.ref_payload() returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('id',pg_temp.ref_id(1),'note','Use this neckline'),jsonb_build_object('id',pg_temp.ref_id(2),'note','Use these sleeves'))$$;
create function pg_temp.ref_send(n integer,payload jsonb default pg_temp.ref_payload(),qty integer default 1) returns public.tailoring_requests language sql as $$
select public.send_tailoring_request_with_references(('e4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'50000000-0000-4000-8000-000000000002','dress','Use these references as inspiration.',qty,current_date+30,true,'{"waist":80}',current_date,payload,'e3000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001',1)
$$;
create function pg_temp.fail_reference_snapshot() returns trigger language plpgsql as $$begin if new.request_id='e4000000-0000-4000-8000-000000000099' then raise exception 'Injected attachment failure' using errcode='23514';end if;return new;end;$$;
create trigger test_reference_failure before insert on public.request_image_references for each row execute function pg_temp.fail_reference_snapshot();
select pg_temp.assert_true((select not public and file_size_limit=5242880 and allowed_mime_types=array['image/jpeg','image/png','image/webp'] from storage.buckets where id='request-reference-images'),'separate private bucket and HTTP upload limits');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.initialize_tailor_profile();
select public.save_tailor_profile('{"shop_name":"Reference Atelier","description":"Bespoke garments for special occasions.","specialties":"Dresses","city":"Colombo","public_address":"123 Public Street","business_phone":"+94112223344","years_experience":5,"accepting_requests":true}',true,1);
select pg_temp.expect_error($q$select public.reserve_request_reference(pg_temp.ref_id(1),'e3000000-0000-4000-8000-000000000001','jpg')$q$,'42501');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000001',true);
select public.save_customer_measurements('{"waist":80}',current_date);
select public.save_customer_design('e5000000-0000-4000-8000-000000000001','{"name":"Reference dress","garment_type":"dress","colour":"ruby","neckline":"round","sleeve":"short","length":"midi"}',null);
do $$begin for i in 1..5 loop perform public.reserve_request_reference(pg_temp.ref_id(i),'e3000000-0000-4000-8000-000000000001','jpg');end loop;end;$$;
select public.reserve_request_reference(pg_temp.ref_id(1),'e3000000-0000-4000-8000-000000000001','jpg');
select pg_temp.expect_error($q$select public.reserve_request_reference(pg_temp.ref_id(6),'e3000000-0000-4000-8000-000000000001','jpg')$q$,'22023');
select pg_temp.expect_error($q$select public.reserve_request_reference(pg_temp.ref_id(6),'e3000000-0000-4000-8000-000000000002','svg')$q$,'22023');
select pg_temp.expect_error('select pg_temp.ref_send(1)','22023');
-- Reproduce the authorization-phase mismatch in 021 before corrective 026.
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(1),'{"contentLength":100,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.assert_true(not exists(select 1 from public.tailoring_requests where customer_id=auth.uid()),'missing objects abort the entire request');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(1),'{"size":5242881,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(1),'{"size":0,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(1),'{"size":100,"mimetype":"text/html"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(1),'{"size":100,"mimetype":"image/png"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(6),'{"size":100,"mimetype":"image/jpeg"}')$q$,'42501');
insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(1),'{"size":5242880,"mimetype":"image/jpeg"}'),('request-reference-images',pg_temp.ref_path(2),'{"size":100,"mimetype":"image/jpeg"}'),('request-reference-images',pg_temp.ref_path(3),'{"size":100,"mimetype":"image/jpeg"}');
select pg_temp.assert_true(public.request_reference_ready(pg_temp.ref_id(1)),'upload metadata confirmation is owner-only and supports 5 MB');
select pg_temp.expect_error('select public.release_request_reference(pg_temp.ref_id(3))','22023');
select pg_temp.expect_error($q$select pg_temp.ref_send(1,'[{"id":"e2000000-0000-4000-8000-000000000001","url":"https://evil"}]')$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.ref_send(1,jsonb_build_array(jsonb_build_object('id',pg_temp.ref_id(1),'note',repeat('x',501))))$q$,'22023');
select pg_temp.expect_error($q$select public.send_tailoring_request_with_references('e4000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000002','dress','References from the wrong batch.',1,current_date+30,false,null,null,pg_temp.ref_payload(),'e3000000-0000-4000-8000-000000000002')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.ref_send(1,pg_temp.ref_payload()||pg_temp.ref_payload())$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.ref_send(1,pg_temp.ref_payload()||pg_temp.ref_payload()||pg_temp.ref_payload())$q$,'22023');
select pg_temp.expect_error('select pg_temp.ref_send(1,pg_temp.ref_payload(),0)','23514');
select pg_temp.expect_error('select pg_temp.ref_send(99)','23514');
select pg_temp.assert_true((select count(*)=0 from public.request_image_references),'injected attachment failure rolls back all reference snapshots');
select pg_temp.assert_true(not exists(select 1 from public.request_design_snapshots where design_id='e5000000-0000-4000-8000-000000000001'),'injected failure rolls back design snapshot');
select pg_temp.assert_true(not exists(select 1 from public.request_measurement_snapshots),'injected failure rolls back measurements');
select pg_temp.assert_true((select attached_at is null from public.customer_designs where id='e5000000-0000-4000-8000-000000000001'),'injected failure rolls back design attachment lock');
select pg_temp.ref_send(1);select pg_temp.ref_send(1);
select pg_temp.assert_true((select count(*)=2 and bool_and(note in('Use this neckline','Use these sleeves')) from public.request_image_references),'one fixed copy of each image and note after retry');
select pg_temp.assert_true((select jsonb_agg(jsonb_build_object('id',upload_id,'note',note) order by ordinal)=pg_temp.ref_payload() from public.request_image_references),'snapshot preserves exact image and note order');
select pg_temp.expect_error($q$select pg_temp.ref_send(1,jsonb_build_array(pg_temp.ref_payload()->1,pg_temp.ref_payload()->0))$q$,'22023');
select pg_temp.expect_error('select public.release_request_reference(pg_temp.ref_id(1))','22023');
select pg_temp.expect_error($q$select pg_temp.ref_send(1,jsonb_set(pg_temp.ref_payload(),'{0,note}','"Changed note"'))$q$,'22023');
select pg_temp.expect_error('select pg_temp.ref_send(2)','42501');
select pg_temp.expect_error('update public.request_image_references set note=''edited''','42501');
select pg_temp.expect_error('delete from public.request_image_references','42501');
select pg_temp.expect_error('update public.request_reference_uploads set submitted_request_id=null','42501');
update storage.objects set metadata='{"size":200,"mimetype":"image/jpeg"}' where bucket_id='request-reference-images';
select pg_temp.assert_true((select metadata->>'size'='5242880' from storage.objects where bucket_id='request-reference-images' and name=pg_temp.ref_path(1)),'updates/upserts cannot replace a submitted file');
delete from storage.objects where bucket_id='request-reference-images' and name=pg_temp.ref_path(1);
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-reference-images' and name=pg_temp.ref_path(1)),'submitted files cannot be deleted even by customer');
delete from storage.objects where bucket_id='request-reference-images' and name=pg_temp.ref_path(3);
select public.release_request_reference(pg_temp.ref_id(3));
select pg_temp.assert_true((select count(*)=0 from public.request_reference_uploads where id=pg_temp.ref_id(3)),'unreferenced files can be deleted via Storage and slots released');
select public.save_customer_measurements('{"waist":90}',current_date);delete from public.customer_measurements;
select pg_temp.ref_send(1);
select pg_temp.assert_true((select values_cm='{"waist":80}'::jsonb from public.request_measurement_snapshots),'reference retries preserve existing immutable measurement snapshots after profile deletion');
select public.send_tailoring_request_with_references('e4000000-0000-4000-8000-000000000003','50000000-0000-4000-8000-000000000002','dress','Request without optional images.',1,current_date+30,false,null,null,'[]',null);
reset role;
update public.request_reference_uploads set created_at=now()-interval '2 hours' where id in(pg_temp.ref_id(1),pg_temp.ref_id(4));
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 and bool_and(id=pg_temp.ref_id(4)) from public.unused_request_reference_uploads()),'cleanup lists only caller aged, unreferenced slots; submitted paths excluded');
select pg_temp.assert_true((select count(*)=0 from public.unused_request_reference_uploads('e3000000-0000-4000-8000-000000000001')),'cleanup excludes the active draft batch even when aged');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.request_image_references),'unrelated customer cannot read attachment notes or paths');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-reference-images'),'unrelated customer cannot sign/download/list files');
select pg_temp.expect_error('select pg_temp.ref_send(4)','42501');
select pg_temp.expect_error('select public.request_reference_ready(pg_temp.ref_id(1))','42501');
select pg_temp.assert_true((select count(*)=0 from public.unused_request_reference_uploads()),'cleanup reveals only caller uploads');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-reference-images'),'admin has no private reference access');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=2 from public.request_image_references),'addressed tailor can read only submitted attachments');
select pg_temp.assert_true((select count(*)=2 from storage.objects where bucket_id='request-reference-images'),'addressed tailor can sign/view submitted files, not draft slots');
delete from storage.objects where bucket_id='request-reference-images';
select pg_temp.assert_true((select count(*)=2 from storage.objects where bucket_id='request-reference-images'),'tailor cannot delete references');
reset role;
-- A deliberately broad legacy policy must not bypass the new bucket guards.
create policy test_broad_reference_access on storage.objects for all to authenticated using(true) with check(true);
set local role authenticated;
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-reference-images'),'restrictive guard blocks older broad read policies');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.ref_path(4),'{"size":100,"mimetype":"image/jpeg"}')$q$,'42501');
reset role;set local role anon;
select pg_temp.expect_error('select * from public.request_image_references','42501');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-reference-images'),'anonymous Storage access denied');
reset role;rollback;
select 'PASS: private request references, upload bounds, ownership, atomic snapshots, retry and Storage protection' as result;
